function moveTo(feature, newLat) {
  const [lon0, lat0] = d3.geoCentroid(feature);
  const toOrigin = d3.geoRotation([-lon0, -lat0]);   // centroid -&gt; (0, 0)
  const toTarget = d3.geoRotation([-lon0, -newLat]); // (lon0, newLat) -&gt; (0, 0)
  const move = pt =&gt; toTarget.invert(toOrigin(pt));
  const walk = c =&gt; typeof c[0] === "number" ? move(c) : c.map(walk);
  return {type: "Feature", geometry: {
    type: feature.geometry.type, coordinates: walk(feature.geometry.coordinates)
  }};
}

